// ฟังก์ชันตรวจว่า string เป็นเลขที่หาร 9 ลงตัวหรือไม่
bool divisibleBy9(const string &num) {
    int sum = 0;
    for (char c : num) {
        if (c >= '0' && c <= '9')
            sum = (sum + (c - '0')) % 9;
    }
    return sum == 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string num;
    bool first = true;

    while (cin >> num) {
        // ถ้าไม่ใช่บรรทัดแรก ให้ขึ้นบรรทัดใหม่
        if (!first) cout << '\n';
        first = false;

        // ตรวจว่าเป็นเลขศูนย์ทั้งหมดไหม เช่น "00000"
        bool allZero = true;
        for (char c : num)
            if (c != '0') allZero = false;

        if (allZero) cout << "yes";
        else cout << (divisibleBy9(num) ? "yes" : "no");
    }

    return 0;
}

